import { randomBytes } from 'node:crypto'
import { mkdir, readFile, rename, rm, stat, writeFile } from 'node:fs/promises'
import { dirname, resolve, sep } from 'node:path'
import { DeleteObjectCommand, GetObjectCommand, HeadObjectCommand, NoSuchKey, NotFound, PutObjectCommand, S3Client } from '@aws-sdk/client-s3'

/**
 * Document byte storage (D29/D35). Keys are generated by the server only:
 * `<organizationId>/<ownerType>s/<yyyy>/<mm>/<documentId>.<ext>`. Drivers validate every key.
 */
export interface DocumentStorage {
  readonly driver: string
  put(key: string, data: Uint8Array): Promise<void>
  get(key: string): Promise<Buffer>
  exists(key: string): Promise<boolean>
  delete(key: string): Promise<void>
}

const UUID = '[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}'
export const STORAGE_KEY_RE = new RegExp(`^${UUID}/[a-z_]+s/\\d{4}/\\d{2}/${UUID}\\.[a-z0-9]{2,5}$`)

export function assertStorageKey(key: string): void {
  if (!STORAGE_KEY_RE.test(key)) throw new Error('Invalid storage key')
}

/**
 * Local filesystem driver for development and tests. Not for production: container disks are
 * ephemeral (TAS 7.1); the S3-compatible driver is a W8 prerequisite.
 */
export class LocalStorage implements DocumentStorage {
  readonly driver = 'local'
  private readonly root: string
  constructor(root: string) {
    this.root = resolve(root)
  }

  private path(key: string): string {
    assertStorageKey(key)
    const full = resolve(this.root, key)
    if (!full.startsWith(this.root + sep)) throw new Error('Storage key escapes the storage root')
    return full
  }

  async put(key: string, data: Uint8Array): Promise<void> {
    const target = this.path(key)
    await mkdir(dirname(target), { recursive: true })
    const tmp = `${target}.${randomBytes(4).toString('hex')}.tmp`
    await writeFile(tmp, data, { flag: 'wx' })
    await rename(tmp, target)
  }

  get(key: string): Promise<Buffer> {
    return readFile(this.path(key))
  }

  async exists(key: string): Promise<boolean> {
    try {
      return (await stat(this.path(key))).isFile()
    } catch {
      return false
    }
  }

  async delete(key: string): Promise<void> {
    await rm(this.path(key), { force: true })
  }
}

export interface S3StorageConfig {
  bucket: string
  region: string
  /** Set for a non-AWS S3-compatible endpoint (MinIO, DigitalOcean Spaces, Backblaze B2, …); omit for AWS itself. */
  endpoint?: string
  accessKeyId: string
  secretAccessKey: string
  /** Most non-AWS S3-compatible providers require path-style addressing. */
  forcePathStyle?: boolean
}

/**
 * Production document storage (W8, TAS §7.1): S3-compatible object storage behind the same
 * `DocumentStorage` interface as `LocalStorage`, so no caller distinguishes the two. Credentials
 * are read once from server configuration (never from a client request) and never leave the
 * process; the browser only ever sees a document id, never a bucket, key, or credential (D35).
 */
export class S3Storage implements DocumentStorage {
  readonly driver = 's3'
  private readonly client: S3Client
  private readonly bucket: string

  constructor(config: S3StorageConfig) {
    this.bucket = config.bucket
    this.client = new S3Client({
      region: config.region,
      endpoint: config.endpoint,
      forcePathStyle: config.forcePathStyle,
      credentials: { accessKeyId: config.accessKeyId, secretAccessKey: config.secretAccessKey }
    })
  }

  async put(key: string, data: Uint8Array): Promise<void> {
    assertStorageKey(key)
    await this.client.send(new PutObjectCommand({ Bucket: this.bucket, Key: key, Body: data, ContentLength: data.byteLength }))
  }

  async get(key: string): Promise<Buffer> {
    assertStorageKey(key)
    try {
      const res = await this.client.send(new GetObjectCommand({ Bucket: this.bucket, Key: key }))
      const chunks: Buffer[] = []
      // The AWS SDK v3 body is a Node Readable in this runtime.
      for await (const chunk of res.Body as AsyncIterable<Buffer>) chunks.push(Buffer.isBuffer(chunk) ? chunk : Buffer.from(chunk))
      return Buffer.concat(chunks)
    } catch (err) {
      if (err instanceof NoSuchKey) throw Object.assign(new Error(`No such key: ${key}`), { code: 'ENOENT' })
      throw err
    }
  }

  async exists(key: string): Promise<boolean> {
    assertStorageKey(key)
    try {
      await this.client.send(new HeadObjectCommand({ Bucket: this.bucket, Key: key }))
      return true
    } catch (err) {
      if (err instanceof NotFound) return false
      const status = (err as { $metadata?: { httpStatusCode?: number } }).$metadata?.httpStatusCode
      if (status === 404) return false
      throw err
    }
  }

  async delete(key: string): Promise<void> {
    assertStorageKey(key)
    await this.client.send(new DeleteObjectCommand({ Bucket: this.bucket, Key: key }))
  }
}

/**
 * Reconciliation sweep (W8): finds documents whose database row has no corresponding object,
 * and (optionally) objects with no database row. Read-only; callers decide remediation.
 */
export interface ReconciliationResult {
  missingObjects: Array<{ documentId: string; storageKey: string }>
  checked: number
}

export async function reconcileStorage(
  storage: DocumentStorage,
  documents: ReadonlyArray<{ documentId: string; storageKey: string }>
): Promise<ReconciliationResult> {
  const missingObjects: ReconciliationResult['missingObjects'] = []
  for (const doc of documents) {
    if (!(await storage.exists(doc.storageKey))) missingObjects.push(doc)
  }
  return { missingObjects, checked: documents.length }
}
